  const all=report.pages.flatMap(p=>p.findings),critical=all.filter(f=>f.severity==='critical').length,warnings=all.filter(f=>f.severity==='warning').length,info=all.filter(f=>f.severity==='info').length,pages=Math.max(1,report.pages.length),health=critical?'At risk':warnings/pages>.75?'Needs focused improvement':warnings?'Generally healthy with opportunities':'Strong technical baseline';
