      const credentials = await loadGoogleCredentials(); if (!credentials) return json(response, 400, { error: 'Save a Google OAuth client locally before connecting.' });
      const state = randomUUID(), redirectUri = `http://127.0.0.1:${port}/api/google/callback`, authorization = createGoogleAuthorization(credentials.clientId, redirectUri, state);
      googleAuthorizations.set(state, { verifier: authorization.verifier, redirectUri, expires: Date.now() + 10 * 60_000 });
      return json(response, 200, { authorizationUrl: authorization.url });
